package mz.co.aprendaacodar.payment.service;
import mz.co.aprendaacodar.common.response.PageResponse;import org.springframework.data.domain.Pageable;
import mz.co.aprendaacodar.common.enums.Enums.*;import mz.co.aprendaacodar.common.exception.*;import mz.co.aprendaacodar.enrollment.entity.CourseEnrollment;import mz.co.aprendaacodar.enrollment.repository.EnrollmentRepository;import mz.co.aprendaacodar.payment.dto.PaymentDtos.*;import mz.co.aprendaacodar.payment.entity.Payment;import mz.co.aprendaacodar.payment.repository.PaymentRepository;import mz.co.aprendaacodar.user.entity.User;import mz.co.aprendaacodar.user.repository.UserRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
import mz.co.aprendaacodar.audit.service.AuditService;
import mz.co.aprendaacodar.storage.StorageService;
@Service public class PaymentService {
 private final PaymentRepository payments;private final EnrollmentRepository enrollments;private final UserRepository users;private final AuditService audit;private final StorageService storage;
 public PaymentService(PaymentRepository p,EnrollmentRepository e,UserRepository u,AuditService audit,StorageService storage){payments=p;enrollments=e;users=u;this.audit=audit;this.storage=storage;}
 @Transactional public Response submit(UUID student,UUID enrollmentId,SubmitRequest r){CourseEnrollment e=enrollments.findById(enrollmentId).orElseThrow(()->new ResourceNotFoundException("Inscrição não encontrada."));if(!e.getStudent().getId().equals(student))throw new ForbiddenOperationException("Não pode submeter pagamento por esta inscrição.");if(r.proofFileKey()!=null&&!r.proofFileKey().startsWith("payment-proofs/"+student+"/"+enrollmentId+"/"))throw new BusinessException("O comprovativo não corresponde a esta inscrição.");if(e.getStatus()!=EnrollmentStatus.PENDING_PAYMENT&&e.getStatus()!=EnrollmentStatus.REJECTED)throw new BusinessException("A inscrição não aceita novos pagamentos neste estado.");if(payments.existsByTransactionReference(r.transactionReference()))throw new BusinessException("Esta referência de transação já foi utilizada.");if(payments.findAllByEnrollmentId(enrollmentId).stream().anyMatch(p->p.getStatus()==PaymentStatus.PENDING_REVIEW))throw new BusinessException("Já existe um pagamento pendente de validação.");Payment p=payments.save(new Payment(e,r.method(),r.transactionReference().trim(),r.proofFileKey()));e.underReview();return map(p);}
 @Transactional(readOnly=true) public PageResponse<Response> mine(UUID student,Pageable pageable){return PageResponse.from(payments.findAllByEnrollmentStudentId(student,pageable),this::map);}@Transactional(readOnly=true) public PageResponse<Response> all(Pageable pageable){return PageResponse.from(payments.findAll(pageable),this::map);}
 @Transactional(readOnly=true) public PageResponse<Response> byStudent(UUID student,Pageable pageable){if(!users.existsById(student))throw new ResourceNotFoundException("Utilizador não encontrado.");return PageResponse.from(payments.findAllByEnrollmentStudentId(student,pageable),this::map);}
 @Transactional(readOnly=true) public Response get(UUID id){return map(payments.findById(id).orElseThrow(()->new ResourceNotFoundException("Pagamento não encontrado.")));}
 @Transactional public Response approve(UUID admin,UUID id){Payment p=find(id);User actor=user(admin);p.approve(actor);p.getEnrollment().activate(actor,EnrollmentSource.PAYMENT);audit.record(actor,"PAYMENT_APPROVED","Payment",id,Map.of("enrollmentId",p.getEnrollment().getId().toString()));return map(p);}
 @Transactional public Response reject(UUID admin,UUID id,String reason){Payment p=find(id);User actor=user(admin);p.reject(actor,reason);p.getEnrollment().reject();audit.record(actor,"PAYMENT_REJECTED","Payment",id,Map.of("reason",reason));return map(p);}
 private Payment find(UUID id){return payments.findById(id).orElseThrow(()->new ResourceNotFoundException("Pagamento não encontrado."));}private User user(UUID id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("Utilizador não encontrado."));}
 private Response map(Payment p){return new Response(p.getId(),p.getEnrollment().getId(),p.getAmount(),p.getCurrency(),p.getMethod(),p.getTransactionReference(),p.getProofFileKey()==null?null:storage.url(p.getProofFileKey(),false),p.getStatus(),p.getSubmittedAt(),p.getReviewedAt(),p.getRejectionReason());}
}
